import logging
import os
import secrets

DEFAULT_HOST = "0.0.0.0"
DEFAULT_PORT = 5000
DEFAULT_DATABASE_URL = "sqlite:///tasks.db"  # Flask-SQLAlchemy stores it in instance/tasks.db

logger = logging.getLogger(__name__)


class Settings:
    """Every setting of the application, read from the environment."""

